package br.com.marquesautodetail.api.servico; import br.com.marquesautodetail.api.servico.dto.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController public class ServicoController{ private final ServicoService service; public ServicoController(ServicoService service){this.service=service;} @GetMapping("/empresas/{empresaId}/servicos") public List<ServicoResponse> listar(@PathVariable Long empresaId){return service.listarPorEmpresa(empresaId);} @PostMapping("/empresas/{empresaId}/servicos") public ServicoResponse criar(@PathVariable Long empresaId,@RequestBody ServicoRequest r){return service.criar(empresaId,r);} @PutMapping("/servicos/{id}") public ServicoResponse atualizar(@PathVariable Long id,@RequestBody ServicoRequest r){return service.atualizar(id,r);} @DeleteMapping("/servicos/{id}") public void remover(@PathVariable Long id){service.remover(id);} }
